import Foundation

// =====================================================
// TwinTrack — native Swift port of the frozen Ridge pipeline
// =====================================================
//
// Source of truth: ml/models/twintrack_model.joblib
// Parameters generated by: ml/src/export_for_swift.py
//
// Prediction contract (verified bit-identical to sklearn
// Pipeline.predict across all 200 holdout rows):
//
//     z_i     = (x_i - mean_i) / scale_i
//     raw     = dot(coef, z) + intercept
//     clamped = min(100, max(0, raw))
//
// Use Double everywhere. Float32 will not hold 1e-6 on `steps`,
// whose scale is ~2478.
// =====================================================

/// Feature order is load-bearing. It must never be reordered.
/// Do NOT source coefficients from ml/results/feature_coefficients.csv —
/// that file is sorted by |coefficient| for charting, not by feature order.
enum TwinTrackFeature: Int, CaseIterable {
    case sleepHours = 0
    case steps = 1
    case exerciseMinutes = 2
    case restingHeartRate = 3
    case studyMinutes = 4
    case screenTimeMinutes = 5
    case previousScore = 6

    var key: String {
        switch self {
        case .sleepHours:        return "sleep_hours"
        case .steps:             return "steps"
        case .exerciseMinutes:   return "exercise_minutes"
        case .restingHeartRate:  return "resting_heart_rate"
        case .studyMinutes:      return "study_minutes"
        case .screenTimeMinutes: return "screen_time_minutes"
        case .previousScore:     return "previous_score"
        }
    }
}

struct TwinTrackProfile {
    var sleepHours: Double
    var steps: Double
    var exerciseMinutes: Double
    var restingHeartRate: Double
    var studyMinutes: Double
    var screenTimeMinutes: Double
    var previousScore: Double

    /// Ordered exactly as the model expects.
    var vector: [Double] {
        [sleepHours, steps, exerciseMinutes, restingHeartRate,
         studyMinutes, screenTimeMinutes, previousScore]
    }
}

struct TwinTrackModel {

    // --- StandardScaler (fitted on the 800-row training split, ddof = 0) ---

    static let mean: [Double] = [
        6.9750875,
        6835.025,
        31.021375,
        68.09925000000001,
        90.76825000000001,
        245.52300000000002,
        74.94800000000001,
    ]

    static let scale: [Double] = [
        1.165721232689767,
        2478.3349716846187,
        18.76555103399245,
        8.758956812172327,
        48.136470237622326,
        91.09202926710987,
        12.11120951845851,
    ]

    // --- Ridge (alpha = 10.0, fit_intercept = true) ---

    static let coef: [Double] = [
        1.0313609218864506,
        0.8551817402946157,
        0.5057650814894945,
        0.24125669488872578,
        1.5671184670863296,
        -0.9375490969179391,
        6.4394301275765775,
    ]

    static let intercept: Double = 67.90012499999999

    // --- Observed training ranges, for extrapolation warnings only.
    //     These never affect the prediction. ---

    static let trainingRange: [(low: Double, high: Double)] = [
        (4.0, 10.0),        // sleep_hours
        (1000.0, 14286.0),  // steps
        (0.0, 91.2),        // exercise_minutes
        (45.0, 95.8),       // resting_heart_rate
        (0.0, 262.7),       // study_minutes
        (30.0, 531.7),      // screen_time_minutes
        (38.2, 100.0),      // previous_score
    ]

    /// Unclamped model output. This is what evaluate.py and baselines.py score.
    static func predictRaw(_ features: [Double]) -> Double {
        precondition(
            features.count == coef.count,
            "TwinTrack expects exactly \(coef.count) features in fixed order."
        )

        var total = intercept

        for i in 0..<features.count {
            let z = (features[i] - mean[i]) / scale[i]
            total += coef[i] * z
        }

        return total
    }

    /// Presentation-layer output, clamped to a valid percentage.
    /// Mirrors predict_score() in the Python assistant.
    static func predict(_ features: [Double]) -> Double {
        min(100.0, max(0.0, predictRaw(features)))
    }

    static func predictRaw(_ profile: TwinTrackProfile) -> Double {
        predictRaw(profile.vector)
    }

    static func predict(_ profile: TwinTrackProfile) -> Double {
        predict(profile.vector)
    }

    /// Features whose value sits outside the observed training range.
    static func extrapolatedFeatures(_ features: [Double]) -> [TwinTrackFeature] {
        TwinTrackFeature.allCases.filter { feature in
            let value = features[feature.rawValue]
            let bounds = trainingRange[feature.rawValue]
            return value < bounds.low || value > bounds.high
        }
    }
}

// =====================================================
// GOLDEN VECTOR HARNESS
// =====================================================
//
// Decodes ml/export/golden_profiles.json and asserts parity with Python.
// Wire this into an XCTest case; it should pass at 1e-6 with headroom.
// =====================================================

struct GoldenProfile: Decodable {
    let name: String
    let note: String
    let inputs: [String: Double]
    let expectedRaw: Double
    let expectedClamped: Double

    enum CodingKeys: String, CodingKey {
        case name, note, inputs
        case expectedRaw = "expected_raw"
        case expectedClamped = "expected_clamped"
    }

    /// Rebuilds the ordered vector from the keyed dictionary,
    /// so a JSON key-order change can never silently reorder features.
    var vector: [Double] {
        TwinTrackFeature.allCases.map { inputs[$0.key]! }
    }
}

struct GoldenFile: Decodable {
    let tolerance: Double
    let featureOrder: [String]
    let profiles: [GoldenProfile]

    enum CodingKeys: String, CodingKey {
        case tolerance, profiles
        case featureOrder = "feature_order"
    }
}

enum GoldenRunner {

    @discardableResult
    static func run(fileURL: URL) throws -> Int {
        let data = try Data(contentsOf: fileURL)
        let golden = try JSONDecoder().decode(GoldenFile.self, from: data)

        // Guard the contract itself, not just the numbers.
        precondition(
            golden.featureOrder == TwinTrackFeature.allCases.map(\.key),
            "Feature order drift between Swift and the Python export."
        )

        var worstRaw = 0.0
        var failures: [String] = []

        for profile in golden.profiles {
            let vector = profile.vector

            let rawDelta = abs(TwinTrackModel.predictRaw(vector) - profile.expectedRaw)
            let clampedDelta = abs(TwinTrackModel.predict(vector) - profile.expectedClamped)

            worstRaw = max(worstRaw, rawDelta)

            if rawDelta > golden.tolerance || clampedDelta > golden.tolerance {
                failures.append(
                    "\(profile.name): raw Δ=\(rawDelta), clamped Δ=\(clampedDelta)"
                )
            }
        }

        if !failures.isEmpty {
            fatalError("Golden parity FAILED:\n" + failures.joined(separator: "\n"))
        }

        print("Golden parity OK — \(golden.profiles.count) profiles, worst Δ=\(worstRaw)")
        return golden.profiles.count
    }
}
